const V32_INTL_BY_ID=new Map();
for(const item of V32_INTERNATIONAL_RECIPES){
 const id=Number(item.id),en=item.locales&&item.locales['en-GB'],pt=item.locales&&item.locales['pt-BR'];
 if(!Number.isInteger(id)||id<96||id>116||!en||!pt||RECIPES.some(x=>Number(x.id)===id))throw new Error('V3.5 international recipe/locale collision: '+id);
 const r={id,title:en.title,emoji:V32_INTL_FLAG[item.country]||'🌍',category:'International',country:item.country,description:en.description,fact:en.description,method:en.method||'Guided cooking',time:(en.estimatedHandsOnMinutes||20)+' min',servings:en.servings||2,yieldText:'Makes '+(en.servings||2)+' servings',ingredients:v32InternationalIngredientList(en),steps:v32InternationalSteps(en),safety:en.adultHelp,adultHelp:en.adultHelp,allergens:en.allergens||[],crossContact:en.crossContact||'',international:en.international,nutrition:en.nutrition,publicationStatus:item.publicationStatus||'REVIEW_ONLY_PENDING_INDEPENDENT_REVIEW',reviewGates:item.reviewGates||{},artworkStatus:item.artworkStatus||'PENDING_REVIEW'};
 RECIPES.push(r);
 PT_RECIPES[id]={title:pt.title,description:pt.description,ingredients:v32InternationalIngredientList(pt),steps:v32InternationalSteps(pt),safety:pt.adultHelp,adultHelp:pt.adultHelp,crossContact:pt.crossContact||''};
 const dish=V32_INTL_ROOT+en.finishedDish;
 NEW_RECIPE_ART[id]={hero:dish,dish,status:item.publicationStatus==='DRAFT_REVIEW_ONLY'?'draft-review-only':'review-only'};
 BATCH_META[id]={title:pt.title,line:pt.description,steps:v32InternationalSteps(pt),titles:pt.steps.map(x=>x.title),tools:pt.equipment,stepCells:pt.steps.map((_,i)=>i)};
 STEP_GUIDES[id]=en.steps.map(x=>({title:x.title,tip:x.safety,safety:x.safety,adultAssist:x.adultAssist,art:V32_INTL_ROOT+x.image.path}));
 V32_INTL_BY_ID.set(id,{record:r,item});
}
