function resolveWebArtworkSource(source){const value=String(source||'').trim();if(/^data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]+$/i.test(value))return value;try{const decodedValue=decodeURIComponent(value);if(/(?:^|\/)\.\.(?:\/|$)/.test(decodedValue.split(/[?#]/,1)[0]))return '';const base=new URL('./',document.baseURI),candidate=new URL(value,document.baseURI);if(candidate.origin!==location.origin||candidate.protocol!==location.protocol)return '';let pathname=decodeURIComponent(candidate.pathname),basePath=decodeURIComponent(base.pathname);if(!pathname.startsWith(basePath))return '';let relative=pathname.slice(basePath.length).replace(/^\/+/, '');if(/^content\/international\/countries\//i.test(relative))relative='international-wave-1/'+relative;const embedded=/^assets\/embedded\/[a-f0-9]{64}\.(?:svg|png|webp|jpe?g|gif)$/i.test(relative),international=/^international-wave-1\/content\/international\/countries\/[a-z0-9-]+\/[0-9]{3}-[a-z0-9-]+\/artwork\/(?:(?:finished\/)?finished-dish\.(?:png|webp)|ingredients\/[a-z0-9-]+\.(?:png|webp)|steps\/step-[0-9]{2}\.(?:png|webp))$/i.test(relative);return embedded||international?new URL(relative,base).href:''}catch{return ''}}function v33FinishedDishSource(recipe){try{const html=homeDishThumb(recipe),src=html.match(/<img\b[^>]*\bsrc=["']([^"']+)["']/i)?.[1]||'';return resolveWebArtworkSource(src)}catch{return ''}}
