/* __V3_CREATIONS_MODEL_START__ */
function v3CreationRecipeId(entry,hasRecipe){const raw=entry&&typeof entry==='object'?entry.recipeId:entry,id=Number(raw);return Number.isSafeInteger(id)&&id>0&&!!hasRecipe(id)?id:null}
function v3CreationDateValue(entry){if(!entry||typeof entry!=='object')return null;for(const value of [entry.completedAt,entry.savedAt,entry.completedDate,entry.createdAt,entry.date]){if(value===null||value===undefined||value==='')continue;const time=typeof value==='number'?value:Date.parse(String(value));if(Number.isFinite(time))return new Date(time).toISOString()}return null}
function v3NormalizeCreationRecords(entries,done,migrated,hasRecipe){const records=[],extras=[],byId=new Map();let changed=!Array.isArray(entries);const accept=entry=>{const id=v3CreationRecipeId(entry,hasRecipe);if(id===null){extras.push(entry);return}const source=entry&&typeof entry==='object'?entry:{},completedAt=v3CreationDateValue(source),old=byId.get(id);if(old){for(const key of Object.keys(source))if(!Object.prototype.hasOwnProperty.call(old,key)){old[key]=source[key];changed=true}changed=true;return}const record={...source,recipeId:id,completedAt};if(!(entry&&typeof entry==='object')||Number(source.recipeId)!==id||source.completedAt!==completedAt)changed=true;records.push(record);byId.set(id,record)};(Array.isArray(entries)?entries:[]).forEach(accept);if(!migrated)(Array.isArray(done)?done:[]).forEach(accept);if(!migrated)changed=true;return{records,entries:[...records,...extras],migrated:true,changed}}
function v3UpsertCreationRecords(entries,id,completedAt,hasRecipe){const target=Number(id);if(!Number.isSafeInteger(target)||target<=0||!hasRecipe(target))return Array.isArray(entries)?entries:[];const normalized=v3NormalizeCreationRecords(entries,[],true,hasRecipe),current=normalized.records.find(item=>item.recipeId===target),date=v3CreationDateValue({completedAt})||new Date().toISOString();if(current)current.completedAt=date;else normalized.records.push({recipeId:target,completedAt:date});return[...normalized.records,...normalized.entries.filter(item=>v3CreationRecipeId(item,hasRecipe)===null)]}
function v3RemoveCreationRecords(entries,id,hasRecipe){const target=Number(id);return(Array.isArray(entries)?entries:[]).filter(entry=>v3CreationRecipeId(entry,hasRecipe)!==target)}
function v3ClearCreationRecords(entries,hasRecipe){return(Array.isArray(entries)?entries:[]).filter(entry=>v3CreationRecipeId(entry,hasRecipe)===null)}
/* __V3_CREATIONS_MODEL_END__ */
function v3HasCreationRecipe(id){return!!find(id)}
function v3EnsureCreationRecords(){const wasMigrated=state.myCreationsV35MigrationComplete===true,n=v3NormalizeCreationRecords(state.myCreations,state.done,wasMigrated,v3HasCreationRecipe);if(n.changed||!wasMigrated){state.myCreations=n.entries;state.myCreationsV35MigrationComplete=true;save()}return n.records}
function v3AddCompletedDish(id){const recipeId=Number(id);if(!v3HasCreationRecipe(recipeId))return;v3EnsureCreationRecords();state.myCreations=v3UpsertCreationRecords(state.myCreations,recipeId,new Date().toISOString(),v3HasCreationRecipe);save()}
